    grade_totals = df.groupby('grade', observed=False)['salary'].sum()
    hourly_rates = df['hourly_rate'].values
    area_under_rate = np.trapezoid(hourly_rates)
    return {'totals': grade_totals, 'integral': area_under_rate}

